function slugify(value: string) { return value.toLowerCase().replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }
function grade(score: number): CareerGrade {
  const values: Array<[number, CareerGrade]> = [[92,"A+"],[86,"A"],[80,"A-"],[74,"B+"],[68,"B"],[62,"B-"],[56,"C+"],[50,"C"],[44,"C-"],[38,"D+"],[32,"D"],[26,"D-"]];
  return values.find(([minimum]) => score >= minimum)?.[1] ?? "F";
}
export function careerGradeLabel(value: CareerGrade) { return value.startsWith("A") ? value === "A+" ? "Exceptional" : "Very strong" : value.startsWith("B") ? "Above average" : value.startsWith("C") ? "Mixed" : value.startsWith("D") ? "Weak" : "Very weak"; }
function result(score: number, explanation: string, factors: string[]): CareerGradeResult { const value = grade(Math.max(0, Math.min(100, score))); return { grade: value, label: careerGradeLabel(value), explanation, factors }; }
function buildGrades(profile: Profile, domain: Domain): CareerRecord["grades"] {
  const midpoint = (profile.hours[0] + profile.hours[1]) / 2;
  const compensation = profile.salary ? Math.min(98, 38 + profile.salary / 1900) : 50;
  const market = Math.max(18, Math.min(98, 51 + profile.growth * 2.15));
  const workLife = Math.max(25, Math.min(94, 116 - midpoint * 1.25));
  const educationPenalty = /Doctor|professional/.test(profile.education) ? 31 : /Master/.test(profile.education) ? 20 : /Bachelor/.test(profile.education) ? 10 : 0;
  const access = 96 - educationPenalty - domain.competition * .42;
  const resilience = 37 + domain.factors.physical * 9 + domain.factors.trust * 7 + domain.factors.accountability * 6 + domain.factors.interpersonal * 6 + domain.factors.judgment * 7 - domain.factors.routine * 8 - domain.factors.digital * 4;
  const upside = 35 + domain.factors.complementarity * 13 + domain.factors.digital * 8 + Math.max(0, profile.growth) * .4;
  const stability = domain.stability + Math.max(-10, Math.min(10, profile.growth));
  const outlook = market * .32 + stability * .24 + resilience * .2 + upside * .24;
  return {
    compensation: result(compensation, profile.salary ? `The ${profile.basisTitle.toLowerCase()} U.S. median is ${new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(profile.salary)}.` : "A reliable occupation-level U.S. figure is not available.", ["BLS U.S. median wage", profile.basisTitle]),
    jobMarket: result(market, `BLS projects ${profile.growth}% employment change for the mapped occupation from 2024 to 2034.`, ["BLS 2024–34 projection", `${profile.growth}% projected change`]),
    workLife: result(workLife, `Typical schedules are estimated around ${profile.hours[0]}–${profile.hours[1]} hours, with substantial employer variation.`, ["Typical weekly-hours range", "Schedule predictability and stress burden"]),
    entryAccessibility: result(access, `Entry reflects ${profile.education.toLowerCase()} and the field’s recruiting competition.`, [profile.education, "Recruiting competition", "Licensure where applicable"]),
    stability: result(stability, "Stability combines current occupational demand with the durability and accountability of the work.", ["Economic necessity", "Regulatory or operational accountability", "BLS demand direction"]),
    aiResilience: result(resilience, "Resilience reflects how much core value depends on physical presence, trust, accountability, interpersonal work, and non-routine judgment.", ["Task routineness", "Physical presence", "Human trust", "Accountable judgment"]),
    aiUpside: result(upside, "Upside reflects how strongly AI tools could accelerate analysis, drafting, design, or technical work while people retain responsibility.", ["Digital-task share", "Technical complementarity", "Demand for validated outputs"]),
    longTermOutlook: result(outlook, `Current evidence suggests a ${profile.growth >= 8 ? "growing" : profile.growth < 0 ? "contracting" : "broadly steady"} market over the next decade, shaped by demand, skill supply, and task-level AI change.`, ["Job market", "Career stability", "AI resilience", "AI upside"]),
  };
}
function buildCareer(seed: Seed): CareerRecord {
  const [name, category, profileKey, domainKey, focus, aliases = []] = seed;
  const profile = profiles[profileKey]; const domain = domains[domainKey]; const slug = slugify(name);
  const grades = buildGrades(profile, domain);
  const aiImpact: CareerRecord["ai"]["impact"] = grades.aiResilience.grade.startsWith("A") && grades.aiUpside.grade.startsWith("A") ? "Strongly Augmented" : ["A","B"].some((letter) => grades.aiUpside.grade.startsWith(letter)) && !grades.aiResilience.grade.startsWith("D") ? "Likely Augmented" : grades.aiResilience.grade.startsWith("D") || grades.aiResilience.grade === "F" ? "Meaningful Automation Risk" : "Mixed / Reshaped";
  const salary = profile.salary ? { median: profile.salary, entryRange: [Math.round(profile.salary * .62 / 1000) * 1000, Math.round(profile.salary * .82 / 1000) * 1000] as [number,number], experiencedRange: [Math.round(profile.salary * 1.12 / 1000) * 1000, Math.round(profile.salary * 1.55 / 1000) * 1000] as [number,number], basisTitle: profile.basisTitle, note: profile.note ?? "Representative BLS median for the mapped occupation; location, industry, experience, and employer change compensation." } : { basisTitle: profile.basisTitle, note: "Not reliably available for this specific role." };
  return { id: `career:${slug}`, slug, name, aliases, category, industry: category, description: `${name} ${focus}.`, summary: `${grades.compensation.label} earning potential and a ${grades.jobMarket.label.toLowerCase()} labor-market signal, with ${grades.entryAccessibility.label.toLowerCase()} entry accessibility and a ${aiImpact.toLowerCase()} AI outlook.`, responsibilities: [`${name}s commonly ${focus}.`, ...domain.responsibilities].slice(0,4), typicalWeek: `A typical week mixes ${domain.responsibilities.map((item) => item.toLowerCase()).join(", ")}. The balance changes by employer, seniority, and project cycle; the ${profile.hours[0]}–${profile.hours[1]} hour range is an orientation, not a promise.`, salary, hours: { minimum: profile.hours[0], maximum: profile.hours[1], note: "Typical U.S. estimate informed by O*NET work-context patterns and occupational norms; schedules vary by employer." }, education: { level: profile.education, note: "This describes the common U.S. route, not the only valid route." }, majors: domain.majors, skills: domain.skills, entryRoles: domain.entryRoles, progression: domain.progression, remotePotential: domain.remote, intensity: domain.intensity, grades, ai: { impact: aiImpact, currentEffect: `AI is changing parts of ${name.toLowerCase()} work through faster drafting, analysis, search, and quality checks. Exposure describes tasks—not certain job elimination.`, automatableTasks: domain.aiAutomatable, durableTasks: domain.aiDurable, positioning: ["Learn to verify AI-produced work", "Build strong domain fundamentals", "Practice communicating uncertainty and taking responsibility for decisions"], uncertainty: "AI capabilities, adoption, regulation, and employer choices are changing. This 5–10 year outlook is directional, not a prediction." }, advantages: domain.advantages, tradeoffs: domain.tradeoffs, mayEnjoyIf: domain.likes, collegePreparation: domain.prep, opportunityTerms: [...new Set([category, name, ...domain.majors])], relatedCareerIds: [], sources: [{ name: bls, url: profile.salaryUrl, year: 2025, supports: ["U.S. median pay", "2024–34 employment outlook", "typical education"] }, { name: "O*NET OnLine 30.1", url: "https://www.onetonline.org/", year: 2025, supports: ["tasks", "skills", "work context"] }, { name: "ILO–NASK Generative AI and Jobs", url: "https://www.ilo.org/publications/generative-ai-and-jobs-refined-global-index-occupational-exposure", year: 2025, supports: ["task exposure", "augmentation versus automation"] }, { name: "OECD AI exposure measure", url: "https://www.oecd.org/en/publications/the-oecd-ai-exposure-measure_f3da0f0a-en.html", year: 2026, supports: ["AI capability exposure", "5–10 year framing"] }], updatedAt: "2026-09-03" };
}

const built = seeds.map(buildCareer);
const byCategory = new Map<string, CareerRecord[]>();
for (const career of built) byCategory.set(career.category, [...(byCategory.get(career.category) ?? []), career]);
export const careers: CareerRecord[] = built.map((career) => {
  const terms = new Set(career.opportunityTerms.map((item) => item.toLowerCase()));
  const scored = built.filter((candidate) => candidate.id !== career.id).map((candidate) => ({ candidate, score: (candidate.category === career.category ? 5 : 0) + candidate.opportunityTerms.filter((term) => terms.has(term.toLowerCase())).length })).filter((item) => item.score > 0).sort((a,b) => b.score-a.score || a.candidate.name.localeCompare(b.candidate.name)).slice(0,5).map((item) => item.candidate.id);
  return { ...career, relatedCareerIds: scored };
});
export const careerBySlug = (slug: string) => careers.find((career) => career.slug === slug);
export const careerCategories = [...new Set(careers.map((career) => career.category))].sort();
